alter policy "See own membership" on public.family_members using (email = lower(((select auth.jwt())->>'email'))); alter policy "Household reads" on public.family_state using (exists (select 1 from public.family_members where email = lower(((select auth.jwt())->>'email')))); alter policy "Household writes" on public.family_state using (exists (select 1 from public.family_members where email = lower(((select auth.jwt())->>'email')))) with check (exists (select 1 from public.family_members where email = lower(((select auth.jwt())->>'email'))));